      "name": "高齢者みまもり事業",
      "start": 98345,
      "raw": "高齢者みまもり事業",
      "bodyStart": 98345,
      "bodyEnd": 98461,
      "body": "高齢者みまもり事業\n\n利用登録者数\n\n8 名（令和 7 年 3 月末現在）\n\n生活環境や家族環境等により日常の安否確認が困難な高齢者への訪問による見守りサービス。\n毎月 1 回、郵便局員が訪問し、その様子を離れて暮らす家族へ報告。\n",
      "amounts": [],
