      "bodyStart": 98714,
      "bodyEnd": 98880,
      "body": "高齢者世帯等買い物支援事業\n利用登録者数 27 名\n\n（令和 7 年 3 月末現在）\n\n登録商店 5 店舗\n\n利用件数延べ 436 件\n\n村内の商店が、高齢者等世帯に注文を受けた商品を配達。配達時には声かけを行うなどし、\n異変があったときには救急要請や地域包括支援センター等へ連絡をする体制になっており、\n見守り機能も兼ねた事業。\n",
      "amounts": [],
      "purpose": null,
      "purposeStart": null,
      "outcomes": null,
      "outcomeStart": null,
      "warning": "令和6年度主要成果報告の個別高齢者支援事業。利用者数・契約額・助成上限・返納年度別内訳を実支出と混同しない。実績なしの記載はそのまま保持し、ゼロ円と推測しない。",
