      "warning": "令和6年度主要成果報告の個別支援・助成・委託名。表の支給単価、対象経費、財源内訳、利用累計、自己負担、前年度比較、交錯した総事業費を決算額として推測しない。実施記述のないものを実施済みと仮定しない。",
