      "bodyStart": 50065,
      "bodyEnd": 50477,
      "body": "定住促進空き家活用事業\n檜原村内の空き家の利活用を促進するため補助金を交付することにより、村内の活性化及び\n村内への定住を目的としています。\n事業名\n\n件数\n\n補助金額\n\n登録\n\n13 件\n\n650,000 円\n\n移住者入居\n\n6件\n\n600,000 円\n\n空き家家財道具等処分事業\n\n4件\n\n340,000 円\n\n空き家改修事業\n\n5件\n\n3,738,862 円\n\n利子補給\n\n1件\n\n232,838 円\n\n空き家移住事業\n\n5件\n\n500,000 円\n\n空き家移住事業（子ども加算）\n\n0件\n\n0円\n\n空き家仲介事業（提供）\n\n2件\n\n200,000 円\n\n空き家仲介事業（移住）\n\n1件\n\n100,000 円\n\n空き家仲介事業（業者）\n\n1件\n\n100,000 円\n\n38 件\n\n6,461,700 円\n\n空き家登録事業\n\n計\n・村ホームページ新規紹介件数\n\n売買物件\n\n2件\n\n- 51 -\n\n賃貸物件\n\n2件\n\n\n",
