      "start": 50809,
      "raw": "老朽空家除却補助金",
      "fragments": [
        {
          "raw": "老朽空家除却補助金",
          "start": 50809
        }
      ],
      "bodyStart": 50809,
      "bodyEnd": 50917,
      "body": "老朽空家除却補助金\n村内の老朽空き家の所有者に対しその除却に係る費用の一部を補助することにより、村内の\n宅地の利活用の促進及び安全で安心なむらづくりに資することを目的としています。\n件数\n\n補助金額\n0件\n\n0円\n\n",
      "amounts": [],
      "purpose": null,
      "purposeStart": null,
      "outcomes": null,
      "outcomeStart": null,
      "warning": "令和6年度主要成果報告の個別支援・助成・委託名。表の支給単価、対象経費、財源内訳、利用累計、自己負担、前年度比較、交錯した総事業費を決算額として推測しない。実施記述のないものを実施済みと仮定しない。",
