      "bodyStart": 160120,
      "bodyEnd": 160370,
      "body": "神戸国際マス釣場整備事業\n神戸国際マス釣場の整備を行い集客数の増加、地域が取り組む地産地消や伝統漁法の披露を支\n援など檜原村の内水面漁業振興を図ることを目的とした事業です。\n・内水面漁業環境活用施設整備事業（東京都補助事業）\n神戸国際マス釣場建替工事\n132,946,000 円\n【事業費の内訳】 東京都\n87,243,000 円\n檜原村\n45,703,000 円\n件\n\n名\n\n金\n\n額\n\n請負業者\n\n備 考\n神戸国際マス釣場建\n替工事の建築に伴う\n施工監理\n既存施設建物解体\n146 ㎡、基礎撤去\n",
