      "body": "檜原村中学生海外派遣事業\n村内在住の中学生を対象に、学力の向上、学習意欲の喚起を促し、未来の社会を創る人材としての\n自覚を高めるため、海外派遣事業を行った。なお、平成 29 年度より利島村と合同で派遣を実施している。\n\n事\n\n業\n\n名\n\n海外派遣事業\n説明会\n\n実\n\n施\n\n日\n\n遣\n\n期\n\n所\n\n3 月 14 日\n6月7日\n\n檜原村役場\n\n７月 2 日\n\n7 月 25 日～\n派\n\n場\n\n間\n\n8月6日\n（11 泊 13 日）\n\n帰 国 報 告 会\n\n10 月 1 日\n\n参加人員\n\n及び\n\n事前説明会\n\n7名\n\n渡航について\n\n8名\n\n英会話教室等\n中学 2 年生 8 名\n引率者 4 名\n\n20 名\n\n- 245 -\n\n利島中学 2 年生 2 名\n利島中学 3 年生 4 名\n\nゴールドコースト\n\n檜原中学校\n\n考\n\n8名\n\nオーストラリア\nマランビンビー\n\n備\n\n利島引率者 2 名\n39 名\n\n派遣生及び保護者\n教育委員・人材育成委員\n\n\n3－2 地域間交流事業\n事業名\n\n内\n\n実施日\n場 所\n\n容\n\n備\n\n考\n\n伊豆七島の青い海と雄大\n子ども体験塾\n利島サマースクール\n（利島村交流事業）\n\nな自然を舞台に体験活動\nを行った。利島村の小学生\nたちとイルカウォッチン\nグ体験や海水浴・花火大会\n\n7 月 20 日（土）\n～22 日（月）\n利島村\n\n参加者 20 名（小 4～小 6）\n引率者 8 名\n\n等を行い交流した。\n海と山の子どもたち\n\n真鶴町、安曇野市及び檜原\n\nの交流会事業\n\n村の子どもたちが、海と山\n\n（真鶴町交流会）\n\nなど自然とのふれあいを\n\n※安曇野市も参加\n\n通じて交流した。\n\n8 月 8 日(木)\n～9 日(金)\n真鶴町\n\n参加者 10 名（小 4～小 6）\n引率者 7 名\n\n音楽の都ウィーンからウ\n\n2 月 7 日（金）\n\n檜原公演：\n\n子ども国際交流音楽\n\nィーンフィルのメンバー\n\n檜原小学校体育館\n\nウィーンの音楽家と児童\n\n祭交流コンサート\n\nを中心とした一流の演奏\n\n（檜原村・羽村市・\n\n家を招き、4 市町村の子ど\n\n奥多摩町・昭島市） もたちが合唱での交流や\n\n秋川流域子ども体験\n塾小中学生駅伝大会\n（檜原村・あきる野市・\n日の出町）\n\nジュニアスキー教室\n（利島村交流事業）\n※ジュニア育成事業\nとの共催事業\n\n生徒 42 名が即興で合唱\n\n2 月 11 日（火・祝） 本公演：\n\n生演奏の鑑賞を行った。\n\nﾌﾟﾘﾓﾎｰﾙゆとろぎ\n\n3 市町村による小中学生駅\n\n12 月 14 日（土）\n\n伝大会として実施し、子ど\n\n秋留台公園\n\nもたちがタイムを競った。\n\n及び周辺道路\n\n野県白馬村での 2 泊 3 日の 1 月 4 日（土）\nウインタースポーツ体験\n\n～6 日（月）\n\nを通じて、スキー等の技術\n\n長野県白馬村\n\n- 246 -\n\n檜原小学校\n\n5 チーム\n\nロードレースの部：3 名\n檜原中学校\n\n1 チーム\n\nロードレースの部：3 名\n参加者 42 名（小 4～中 2）\n\n利島村の子どもたちと、長\n\nと団体行動を学んだ。\n\n合唱団へ 3 名が参加\n\n檜原村：小学生 19 名\n中学生 12 名\n利島村：小学生 7 名\n中学生 4 名\n引率者 17 名\n\n\n",
      "amounts": [],
      "purpose": null,
      "purposeStart": null,
      "outcomes": null,
      "outcomeStart": null,
      "warning": "令和6年度主要成果報告に明記された個別制度・委託単位。過年度累計、契約金額、補助財源、支給基準と年度実績額を混同しない。複合見出しは分割せず保持し、実施件数が零の制度も実施済みとは扱わない。",
      "supportingQuotes": []
