      "body": "（4）歯科健診事業\n①乳幼児歯科健診\n10 か月児から就学前の乳幼児を対象に歯科健診、歯科保健指導等を個別に実施。\n事\n\n業\n\n名\n\n乳幼児歯科健診\n\n実人数\n\n延べ人数\n\n9人\n\n9人\n\n②乳幼児フッ素塗布状況\n1 歳 6 か月から小学 2 年生までの幼児・児童を対象に、虫歯予防のため乳幼児 1 人に対し\n年 2 回に限り無料でフッ素塗布を実施。\n対\n\n象\n\n者\n\n実人数\n\n延べ人数\n\n乳幼児\n\n12 人\n\n20 人\n\n小学生\n\n5人\n\n6人\n\n",
