      "body": "（１）介護予防・日常生活支援総合事業\n①総合事業対象者数 24 名（令和 7 年 3 月 31 日現在）\n・２５項目の質問からなる基本チェックリストを活用し、日常生活に必要な機能の低下の\n有無を判定し、近い将来、要介護となるリスクの高い高齢者を「総合事業対象者」と認定\nし、訪問型サービスや通所型サービスの提供を行っている。\n②介護予防・生活支援サービス事業費\n種類\n\n給付件数\n\n介護予防・生活支援サービス事業費負担金\n訪問型サービスＡ\n通所型サービスＡ\n介護予防ケアマネジメントＡ\n③訪問型サービスＤ補助金\n\n328,708 円\n\n１件あたり\n平均給付額\n\n給付額\n\n426\n\n4,429,812 円\n\n10,399 円\n\n37\n201\n188\n\n311,578 円\n3,219,494 円\n898,740 円\n\n8,421 円\n16,017 円\n4,781 円\n\n１事業者\n\n延べ実施件数件\n\n48 件\n\n要支援者・事業対象者のうち、生活に必要な通院・買い物等の外出に伴う移送及び移送前\n後の支援を行う事業者に対して補助金を交付するもの。\n④一般介護予防事業\n・がんばんべぇ\n\n毎週木曜午前 全 48 回\n\n延べ 375 名\n\n運動機能低下などが認められる 65 歳以上の村民を対象にマット上での運動機能向上トレ\nーニング等を行った。\n・巡回型介護予防教室\n\n全3回\n\n講師派遣の要請のあったいきいきサロン等高齢者活動団体に講師を派遣し、地域で抱える\n健康・介護予防に関する課題に対し運動・栄養改善等の指導を行った。\n・地域リハビリテーション活動支援事業 全 0 回\n介護予防の取組みを機能強化するため、訪問、通所、地域ケア会議、住民主体の通いの場\n等へリハビリテーション専門職を派遣し、介護予防の取り組みを支援する事業。本年度は実\n績なし。\n\n",
