      "body": "（２）包括的支援事業\n①地域包括支援センター\n・介護予防サービス支援計画の作成\n総合事業対象者及び要支援 1・2 と認定された方のケアプラン作成。\n\n- 118 -\n\n\nプラン作成件数\n包括\n委託\n全件\n\n4月\n18\n4\n22\n\n5月\n20\n4\n24\n\n6月\n17\n4\n21\n\n7月\n19\n5\n24\n\n8月\n18\n5\n23\n\n9月\n18\n4\n22\n\n10 月\n19\n4\n23\n\n11 月\n19\n4\n23\n\n12 月\n18\n4\n22\n\n1月\n18\n4\n22\n\n2月\n18\n3\n21\n\n3月\n17\n3\n20\n\n計\n219\n48\n267\n\n・総合相談支援\n地域の高齢者が地域で安心してその人らしい生活を継続していくことができるよう、適切\nなサービス、機関又は制度の利用につなげる等の支援を行った。\n相談件数\n件数\n\n4月\n11\n\n5月\n18\n\n6月\n13\n\n7月\n14\n\n8月\n9\n\n9月\n10\n\n10 月\n12\n\n11 月\n16\n\n12 月\n11\n\n1月\n12\n\n2月\n11\n\n3月\n13\n\n計\n150\n\n・介護事業所連絡会\n実績なし。\n・救急支援事業\n\n救急医療情報キットの設置\n\n災害時や救急時など、非常時に備えて本人の名前や生年月日、緊急連絡先などを専用のボ\nトルに入れて冷蔵庫等所定の場所に目印を付け保管し、緊急時に迅速な対応ができるような\n取り組みを行っている。\n令和 7 年 3 月 31 日現在\n\n救急医療キット設置総数\n\n186 世帯\n\n229 名\n\n②在宅医療・介護連携推進事業（西多摩地域広域行政圏協議会にて共同実施）\n医療と介護の両方を必要とする状態の高齢者が、住みなれた地域で自分らしい暮らしを人\n生の最期まで続けることができるよう、在宅医療と介護を一体的に提供するために医療機関\nや介護事業所などの関係者との連携の推進を図った。\n・地域の医療・介護資源の把握\n地域の医療・介護関係者間の連携等に活用するため、西多摩圏域の医療機関・介護事業所\n等のリストを更新し配布した。\n・医療・介護関係者研修の開催\n令和 6 年 11 月 13 日（水）\n\n「入退院支援における多職種連携」\n\n・住民への普及啓発として講演会を開催\n令和 7 年 1 月 18 日（土）\n\n「最後まであなたらしく生きるために～アドバンス・ケア\nプランニング（人生会議）をはじめてみませんか？」\n\n- 119 -\n\n\n③生活支援体制整備事業\n\n活動日数 12 日\n\n生活支援コーディネーターを配置し、地域サロン等高齢者活動団体に対し運動指導など\nの活動支援を行った。また、高齢者のニーズを把握し新たな高齢者支援サービスの検討を\n行った。\n④認知症施策推進事業\n・認知症地域支援・ケア向上事業\n\n活動日数 12 日\n\n認知症の人が住み慣れた地域で安心して暮らし続けるために、医療機関や介護サービス及\nび地域の支援機関の連携を図るための支援や認知症ケアパスを配布し、認知症の基本的な知\n識や対応方法の周知を行った。また、認知症地域支援推進員を配置し、地域の支援体制の構\n築を図った。\n⑤地域ケア会議の開催\n実績なし。\n\n",
