      "bodyStart": 44710,
      "bodyEnd": 45370,
      "body": "４２．令和６年度東京都市町村総合交付金充当事業\n事\n\n業\n\n名\n\n生活環境改善対策\n\n児童・生徒通学費補助\n\nへき地学校給食\n\n檜原小学校パソコン推進事業\n\n観光ごみ対策\n\n檜原中学校パソコン推進事業\n\n地場産業振興事業\n\n図書館運営事業\n\n観光振興事業\n\n林道災害復旧事業\n\n広域行政圏事業\n\n障害者自立支援給付費\n\nバス路線維持事業\n\n後期高齢者支援事業費\n\n定住促進空き家補助事業\n\n村道補修事業\n\n国民健康保険特別会計繰出金\n\n林道補修事業\n\n福祉作業所運営委託\n\n橋梁補修事業\n\n介護保険特別会計繰出金\n\n河川維持補修事業\n\n介護サービス事業会計繰出金\n\n橋梁長寿命化事業費\n\n後期高齢者医療特別会計繰出金\n\n立山林道開設工事\n\n保育所運営費\n\n南沢林道石積擁壁補修工事\n\n児童館運営委託\n\n神戸岩駐車場改修工事\n\n阿伎留病院企業団負担金\n\n小林家住宅登山道整備改修工事\n\n秋川流域斎組合負担金\n\n温泉センター補修事業費\n\nし尿汲取委託\n\n小沢急傾斜地崩壊防止事業費負担金\n\n一般廃棄物収集委託\n\n村道第７号時坂線側溝改修工事\n\n西秋川衛生組合負担金\n\n有害鳥獣駆除用捕獲檻購入費\n\n簡易水道事業会計繰出金\n\n消防積載車購入費\n\n下水道事業会計繰出金\n\n学校給食調理器具消毒保管機購入費\n\n常備消防委託\n\n小水力発電推進事業\n\n消防施設備品購入\n\n神戸国際マス釣場整備事業\n\n防災無線管理費\n\nエコツーリズム関連事業\n\n学校介助員、学校巡回巡視による教育環境向上\n\n学校給食費負担軽減事業\n\n- 45 -\n\n\n",
